/**
 * Counts are bounded per repository: a slow or unreachable repository, whose abandoned counts keep running, does not
 * stop the Summary, Graphs, Types and Clear pages of other repositories from counting. Statement counts use the
 * repository size, also for a remote repository, whose server answers it for every repository type.
 */
class BrowseCountsPerRepositoryTest {

	private static final ObjectMapper JSON_MAPPER = new ObjectMapper();

	private static final String NS = "urn:test:";

	private final CountDownLatch release = new CountDownLatch(1);

	private final AtomicInteger slowCountsStarted = new AtomicInteger();

	private final List<TransformationServlet> servlets = new ArrayList<>();

	private Repository store;

	private Repository slowStore;

	@BeforeEach
	void setUp() {
		store = new SailRepository(new MemoryStore());
		store.init();
		ValueFactory vf = store.getValueFactory();
		try (RepositoryConnection connection = store.getConnection()) {
			IRI type = vf.createIRI(NS + "Type");
			connection.add(vf.createIRI(NS + "a"), org.eclipse.rdf4j.model.vocabulary.RDF.TYPE, type,
					vf.createIRI(NS + "graph/a"));
			connection.add(vf.createIRI(NS + "b"), vf.createIRI(NS + "p"), vf.createLiteral("b"),
					vf.createIRI(NS + "graph/b"));
			connection.add(vf.createIRI(NS + "c"), vf.createIRI(NS + "p"), vf.createLiteral("c"),
					vf.createIRI(NS + "graph/b"));
			connection.add(vf.createIRI(NS + "d"), vf.createIRI(NS + "p"), vf.createLiteral("d"));
		}
		Repository slowBackend = new SailRepository(new MemoryStore());
		slowBackend.init();
		slowStore = new RepositoryWrapper(slowBackend) {
			@Override
			public RepositoryConnection getConnection() throws RepositoryException {
				return new RepositoryConnectionWrapper(this, super.getConnection()) {
					@Override
					public long size(Resource... contexts) throws RepositoryException {
						blockLikeARemoteCall();
						return super.size(contexts);
					}

					@Override
					public RepositoryResult<Resource> getContextIDs() throws RepositoryException {
						blockLikeARemoteCall();
						return super.getContextIDs();
					}
				};
			}
		};
	}

	@AfterEach
	void tearDown() {
		release.countDown();
		servlets.forEach(TransformationServlet::destroy);
		store.shutDown();
		slowStore.shutDown();
	}

	@Test
	void aSlowRepositoryDoesNotStopTheCountsOfAnotherRepository() throws Exception {
		SummaryServlet slowSummary = init(new SummaryServlet(50), slowStore, "summary");
		for (int visit = 0; visit < BrowseList.MAX_IN_FLIGHT_COUNTS; visit++) {
			List<JsonNode> abandoned = get(slowSummary, "summary", true, null);
			assertThat(metadata(abandoned).path("counts-timed-out").asBoolean()).isTrue();
		}
		assertThat(slowCountsStarted.get()).as("the slow repository's counts are still running")
				.isGreaterThanOrEqualTo(BrowseList.MAX_IN_FLIGHT_COUNTS);

		List<JsonNode> summary = get(init(new SummaryServlet(), store, "summary"), "summary", true, null);
		assertThat(metadata(summary).has("counts-timed-out")).isFalse();
		assertThat(column(summary, 0)).containsExactly("4");
		assertThat(column(summary, 1)).containsExactly("2");

		List<JsonNode> graphs = get(init(new ContextsServlet(), store, "contexts"), "contexts", true, null);
		assertThat(metadata(graphs).has("counts-timed-out")).isFalse();
		assertThat(column(graphs, 1)).containsExactly("1", "2", "1");

		List<JsonNode> types = get(init(new TypesServlet(), store, "types"), "types", true, null);
		assertThat(metadata(types).has("counts-timed-out")).isFalse();
		assertThat(column(types, 1)).containsExactly("1");

		List<JsonNode> clearPage = get(init(new ClearServlet(), store, "clear"), "clear", false, null);
		assertThat(metadata(clearPage).path("context-discovery-complete").asBoolean())
				.as("the Clear page can offer its graphs")
				.isTrue();
		List<JsonNode> clearCounts = get(init(new ClearServlet(), store, "clear"), "clear", true, null);
		assertThat(metadata(clearCounts).path("counts-timed-out").asBoolean()).isFalse();
		assertThat(metadata(clearCounts).path("repository-size").asLong()).isEqualTo(4);
	}

	@Test
	void theCountsOfOneRepositoryStayBoundedAcrossItsPages() throws Exception {
		SummaryServlet slowSummary = init(new SummaryServlet(50), slowStore, "summary");
		for (int visit = 0; visit < BrowseList.MAX_IN_FLIGHT_COUNTS; visit++) {
			get(slowSummary, "summary", true, null);
		}
		int started = slowCountsStarted.get();

		List<JsonNode> graphs = get(init(new ContextsServlet(), slowStore, "contexts"), "contexts", true, null);

		assertThat(metadata(graphs).path("counts-timed-out").asBoolean()).isTrue();
		assertThat(slowCountsStarted.get())
				.as("another page of the slow repository does not start more counts while it is at its limit")
				.isEqualTo(started);
	}

	@Test
	void remoteRepositoriesAreCountedWithTheirSizeAndOnlyTheFilteredGraphsAreCounted() throws Exception {
		List<Resource> countedGraphs = new ArrayList<>();
		Repository remote = remoteRepository(countedGraphs);

		List<JsonNode> summary = get(init(new SummaryServlet(), remote, "summary"), "summary", true, null);
		assertThat(metadata(summary).has("counts-timed-out")).isFalse();
		assertThat(column(summary, 0)).containsExactly("4");

		countedGraphs.clear();
		List<JsonNode> graphs = get(init(new ContextsServlet(), remote, "contexts"), "contexts", true, "GRAPH/B");
		assertThat(column(graphs, 0)).containsExactly(NS + "graph/b");
		assertThat(column(graphs, 1)).containsExactly("2");
		assertThat(countedGraphs).as("a filtered count counts the matching graphs only")
				.containsExactly(store.getValueFactory().createIRI(NS + "graph/b"));

		List<JsonNode> clearCounts = get(init(new ClearServlet(), remote, "clear"), "clear", true, null);
		assertThat(metadata(clearCounts).path("counts-timed-out").asBoolean()).isFalse();
		assertThat(metadata(clearCounts).path("repository-size").asLong()).isEqualTo(4);
		assertThat(column(clearCounts, 1)).containsExactly("1", "2", "1");
	}

	/**
	 * A repository on an RDF4J Server, which may be a federation or a SPARQL endpoint proxy: its size is answered by
	 * the server, but a SPARQL COUNT query streams every member's statements or misreads the default graph.
	 */
	private Repository remoteRepository(List<Resource> countedGraphs) {
		HTTPRepository remote = new HTTPRepository("http://127.0.0.1:9/rdf4j-server", "remote");
		return new RepositoryWrapper(store) {
			@Override
			public RepositoryConnection getConnection() throws RepositoryException {
				return new RepositoryConnectionWrapper(remote, super.getConnection()) {
					@Override
					public long size(Resource... contexts) throws RepositoryException {
						for (Resource context : contexts) {
							synchronized (countedGraphs) {
								countedGraphs.add(context);
							}
						}
						return super.size(contexts);
					}

					@Override
					public TupleQuery prepareTupleQuery(QueryLanguage ql, String query, String baseURI)
							throws MalformedQueryException, RepositoryException {
						throw new UnsupportedOperationException("statement counts must use the repository size");
					}

					@Override
					public Query prepareQuery(QueryLanguage ql, String query, String baseURI)
							throws MalformedQueryException, RepositoryException {
						throw new UnsupportedOperationException("statement counts must use the repository size");
					}
				};
			}

			@Override
			public void shutDown() {
				// the store is shut down by the test
			}
		};
	}

	/** A remote count that has been abandoned keeps blocking in I/O and ignores interrupts. */
	private void blockLikeARemoteCall() {
		slowCountsStarted.incrementAndGet();
		boolean interrupted = false;
		while (true) {
			try {
				release.await(30, TimeUnit.SECONDS);
				break;
			} catch (InterruptedException e) {
				interrupted = true;
			}
		}
		if (interrupted) {
			Thread.currentThread().interrupt();
		}
	}

	private <T extends TransformationServlet> T init(T servlet, Repository repository, String name)
			throws Exception {
		RepositoryInfo info = new RepositoryInfo();
		info.setId(name + "-test");
		servlet.setRepository(repository);
		servlet.setRepositoryManager(mock(RepositoryManager.class));
		servlet.setRepositoryInfo(info);
		servlet.init(TestServletConfig.withParams(name, "cookie-max-age", "300"));
		servlets.add(servlet);
		return servlet;
	}

	private static List<JsonNode> get(TransformationServlet servlet, String view, boolean counts, String filter)
			throws Exception {
		MockHttpServletRequest request = new MockHttpServletRequest("GET", "/" + view);
		request.addHeader("Accept", WorkbenchPageProtocol.ACCEPT);
		if (counts) {
			request.addParameter("counts", "true");
		}
		if (filter != null) {
			request.addParameter("filter", filter);
		}
		MockHttpServletResponse response = new MockHttpServletResponse();
		servlet.service(request, response);
		return response.getContentAsString().lines().map(BrowseCountsPerRepositoryTest::readTree).toList();
	}

	private static JsonNode readTree(String line) {
		try {
			return JSON_MAPPER.readTree(line);
		} catch (Exception e) {
			throw new IllegalStateException(e);
		}
	}

	private static JsonNode metadata(List<JsonNode> records) {
		return records.stream()
				.filter(record -> "metadata".equals(record.path("type").asText()))
				.map(record -> record.path("values"))
				.findFirst()
				.orElse(JSON_MAPPER.createObjectNode());
	}

	private static List<String> column(List<JsonNode> records, int index) {
		List<String> values = new ArrayList<>();
		for (JsonNode record : records) {
			if ("rows".equals(record.path("type").asText())) {
				record.path("values").forEach(row -> {
					JsonNode term = row.get(index);
					values.add(term == null || term.isNull() ? null : term.path("value").asText());
				});
			}
		}
		return values;
	}
}
